#!/usr/bin/env bash
# shellcheck disable=SC1087,SC2329,SC2016  # the wizard library above the STAGES marker is shared, unedited
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES (#7133 slice 0, the person's half). Every step that acts as the person.
# ──────────────────────────────────────────────────────────────────────────

# shellcheck disable=SC1091
source "$(dirname "${BASH_SOURCE[0]}")/common.sh"
ENV_FILE="${ENV_FILE:-${TMPDIR:-/tmp}/forge-lock-verify.env}"

USAGE="usage: person.sh <purlis-forge-lock-verify-NAME | owner/NAME> <setup|fixup|lock|press|automerge|bypass-app-on|bypass-app-off|cleanup>"
[[ $# -eq 2 ]] || die "$USAGE"
PHASE=$2
need_repo_name "${1##*/}"   # before anything touches your credentials
command -v gh >/dev/null 2>&1 || die "gh is needed, signed in as you"
command -v jq >/dev/null 2>&1 || die "jq is needed"
ADMIN="$(gh auth token)" || die "gh is not signed in"
[[ -n "$ADMIN" ]] || die "gh is not signed in"
req_unscoped "$ADMIN" GET /user
LOGIN=$(jqb "GET /user" -r .login); USER_ID=$(jqb "GET /user" -r .id)
[[ -n "$LOGIN" && "$LOGIN" != null ]] || die "cannot read your login: $(observed)"
if [[ "$1" == */* ]]; then
  need_repo "$1"
else
  need_repo_name "$1"; REPO="$LOGIN/$1"
fi
OWNER=${REPO%%/*}
[[ "$OWNER" =~ ^[A-Za-z0-9-]+$ ]] || die "owner '$OWNER' is not a GitHub login; refusing"
ORG_OWNER=false
if [[ "$OWNER" != "$LOGIN" ]]; then
  # An organisation the person administers (an active admin membership), else stop.
  req_unscoped "$ADMIN" GET "/user/memberships/orgs/$OWNER"
  jqb "GET /user/memberships/orgs/$OWNER" -e '.role == "admin" and .state == "active"' >/dev/null \
    || die "$OWNER is neither your account ($LOGIN) nor an organisation you administer: $(observed)"
  ORG_OWNER=true
fi
STATE_NOTE="the chat half, from a chat whose workspace has a clone of $REPO: tools/forge-lock-verify/chat.sh $REPO"

# put_file BRANCH PATH CONTENT MESSAGE: create or update one file as you.
put_file() {
  local sha=""
  req "$ADMIN" GET "/contents/$2?ref=$1"; sha=$(jqb "put_file/$2" -r '.sha // empty')
  req "$ADMIN" PUT "/contents/$2" "$(jq -n --arg m "$4" --arg c "$(b64 "$3")" --arg b "$1" --arg s "$sha" \
    '{message:$m,content:$c,branch:$b} + (if $s == "" then {} else {sha:$s} end)')"
}
# branch_from_main NAME FILE: a branch with one commit, and (with a FILE of "-") nothing else.
branch_from_main() {
  local sha
  req "$ADMIN" GET /git/ref/heads/main; sha=$(jqb "branch_from_main/$1" -r '.object.sha // empty')
  [[ -n "$sha" ]] || die "branch_from_main $1: cannot read main: $(observed)"
  req "$ADMIN" POST /git/refs "{\"ref\":\"refs/heads/$1\",\"sha\":\"$sha\"}"
  [[ "$2" == "-" ]] || put_file "$1" "$2" "$1" "$1"
}
open_pr() { req "$ADMIN" POST /pulls "$(jq -n --arg h "$1" --arg b "${2:-main}" '{title:$h,head:$h,base:$b}')"; }
require_ok() { [[ "$STATUS" == 2* ]] || die "$1 failed: $(observed)"; }

# actor_type for the bypass list: User if GitHub accepts it (B3), else the repository admin role.
bypass_json() { # actor_type actor_id mode
  jq -n --arg t "$1" --argjson id "$2" --arg m "$3" '[{actor_id:$id,actor_type:$t,bypass_mode:$m}]'
}
branches_ruleset() { # bypass_actors_json
  jq -n --argjson b "$1" '{name:"purlis: protected branches",target:"branch",enforcement:"active",
    conditions:{ref_name:{include:["~DEFAULT_BRANCH","refs/heads/release","refs/heads/nightly","refs/heads/release/**"],exclude:[]}},
    rules:[{type:"creation"},{type:"update"},{type:"deletion"},{type:"non_fast_forward"}],bypass_actors:$b}'
}
tags_ruleset() {
  jq -n --argjson b "$1" '{name:"purlis: tags",target:"tag",enforcement:"active",
    conditions:{ref_name:{include:["~ALL"],exclude:[]}},
    rules:[{type:"creation"},{type:"update"},{type:"deletion"}],bypass_actors:$b}'
}
ruleset_id() { req "$ADMIN" GET /rulesets; jqb "ruleset_id/$1" -r --arg n "$1" '[.[]? | select(.name == $n) | .id][0] // empty'; }

# ensure_file BRANCH PATH CONTENT MESSAGE: put_file only when the file is not there yet.
ensure_file() {
  req "$ADMIN" GET "/contents/$2?ref=$1"
  if [[ "$STATUS" == 200 ]]; then say "ok    $1:$2 exists"; return; fi
  [[ "$STATUS" == 404 ]] || die "read $1:$2: $(observed)"
  put_file "$1" "$2" "$3" "$4"; require_ok "create $1:$2"; say "made  $1:$2"
}
# ensure_branch NAME FILE: the branch (with FILE, or "-" for none) unless the branch exists.
ensure_branch() {
  req "$ADMIN" GET "/git/ref/heads/$1"
  if [[ "$STATUS" == 200 ]]; then say "ok    branch $1 exists"; return; fi
  [[ "$STATUS" == 404 ]] || die "read branch $1: $(observed)"
  branch_from_main "$1" "$2"; require_ok "branch $1"; say "made  branch $1"
}
# ensure_pr BRANCH BASE: a pull request from BRANCH (open or not); its base is BASE when it is made,
# and for vf-retarget it is moved to BASE when it is not there.
ensure_pr() {
  local n base
  n=$(pr_num "$ADMIN" "$1")
  if [[ -z "$n" ]]; then
    open_pr "$1" "$2"; require_ok "open pull request $1"; say "made  pull request $1 (base $2)"
    return
  fi
  req "$ADMIN" GET "/pulls/$n"; base=$(jqb "pull $n" -r .base.ref)
  if [[ "$1" == vf-retarget && "$base" != "$2" ]]; then
    req "$ADMIN" PATCH "/pulls/$n" "$(jq -n --arg b "$2" '{base:$b}')"; require_ok "retarget pull request $n to $2"
    say "fixed pull request #$n ($1): base $base -> $2"
  else
    say "ok    pull request #$n ($1) exists, base $base"
  fi
}
# ensure_fixture: everything the chat rows need, each piece made only if it is missing.
ensure_fixture() {
  local _ b
  for _ in 1 2 3 4 5; do req "$ADMIN" GET /git/ref/heads/main; [[ "$STATUS" == 200 ]] && break; sleep 2; done
  require_ok "read main"
  ensure_file main scripts/run.sh $'#!/usr/bin/env bash\nset -eu\necho ok\n' "add scripts/run.sh"
  ensure_file main .github/workflows/ci.yml $'name: ci\non: [push, pull_request, repository_dispatch]\njobs:\n  ci:\n    runs-on: ubuntu-latest\n    env:\n      GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}\n    steps:\n      - uses: actions/checkout@v4\n      - run: bash scripts/run.sh\n' "add ci.yml"
  for b in release nightly; do ensure_branch "$b" -; done
  for b in vf-m0 vf-m1 vf-m2 vf-m3 vf-retarget vf-press vf-auto vf-merges vf-rename; do
    ensure_branch "$b" "$b.txt"
    if [[ "$b" == vf-retarget ]]; then ensure_pr "$b" nightly; else ensure_pr "$b" main; fi
  done
  req "$ADMIN" GET /git/ref/tags/v0
  if [[ "$STATUS" == 200 ]]; then say "ok    tag v0 exists"; fi
  req "$ADMIN" GET /releases/tags/v0
  if [[ "$STATUS" == 200 ]]; then say "ok    release v0 exists"; else
    req "$ADMIN" POST /releases '{"tag_name":"v0","target_commitish":"main","name":"v0"}'; require_ok "release v0"
    say "made  release v0 (and tag v0 if it was missing)"
  fi
}
# repo_exists: success when $REPO exists and carries the throwaway marker; stops when it exists without.
repo_exists() {
  req "$ADMIN" GET ""
  case "$STATUS" in
    200) jqb repo-marker -e --arg m "$MARKER" '.description == $m' >/dev/null \
           || die "$REPO exists but does not carry the throwaway marker; refusing" ;;
    404) return 1 ;;
    *) die "cannot read $REPO: $(observed)" ;;
  esac
}

stage_create_repo() {
  stage "Create the throwaway public repo"
  say "Creates $REPO (public) under $OWNER, with the marker description every script checks."
  say "It holds main, release, nightly, a tag v0 and release v0, ci.yml, and the pull requests the chat rows use."
  say "Safe to re-run: whatever already exists is left alone."
  if repo_exists; then say "$REPO already exists; filling in what is missing."; else
    confirm "Create $REPO now?" || die "stopped"
    local create=/user/repos
    [[ "$ORG_OWNER" == true ]] && create="/orgs/$OWNER/repos"
    req_unscoped "$ADMIN" POST "$create" "$(jq -n --arg n "${REPO##*/}" --arg d "$MARKER" \
      '{name:$n,description:$d,private:false,auto_init:true}')"
    require_ok "create repo"
  fi
  ensure_fixture
  say "Done. Pull requests, branches, tag v0 and release v0 exist."
  pause
}

stage_fixup() {
  stage "Fix up the throwaway repo"
  say "Re-runs the setup steps that need the repo: retargets vf-retarget's pull request to nightly if it is not,"
  say "and makes any missing branch, pull request, tag v0 or release v0. Anything that exists is left alone."
  say "Run it before the lock: a tag ruleset would refuse a missing tag v0."
  repo_exists || die "$REPO does not exist; run: person.sh $REPO setup"
  ensure_fixture
  pause
}

stage_install_app() {
  stage "Install the purlis agent App on the repo"
  if [[ "$ORG_OWNER" == true ]]; then
    say "The App (purlis-purlis-agent) is already installed on $OWNER. Add $REPO to its selected repositories,"
    say "with the permissions of the design's manifest, Administration off."
    open_url "https://github.com/organizations/$OWNER/settings/installations"
    step "Configure purlis-purlis-agent, under 'Repository access' choose 'Only select repositories', add $REPO, and Save."
    pause "Press Enter once $REPO is among the App's selected repositories..."
    return
  fi
  say "Install it on ONLY $REPO, with the permissions of the design's manifest, Administration off."
  ask APP_SLUG "The App's slug (github.com/apps/<slug>):"
  open_url "https://github.com/apps/$APP_SLUG/installations/new"
  step "Choose your account, then 'Only select repositories', then $REPO. Click Install."
  pause "Press Enter once the App is installed on $REPO..."
}

stage_immutable() {
  stage "Immutable releases, then release v1"
  say "Immutable releases protect a release published after the setting is on."
  open_url "https://github.com/$REPO/settings"
  step "Under General, find 'Immutable releases' (Releases section) and turn it on for this repo."
  pause "Press Enter once it is on..."
  printf 'immutable asset\n' >"$WORK/asset.txt"
  req "$ADMIN" GET /releases/tags/v1
  if [[ "$STATUS" == 200 ]]; then say "release v1 already exists; leaving it."; else
    gh release create v1 "$WORK/asset.txt" --repo "$REPO" --target main --title v1 --notes "immutable probe" \
      || warn "creating release v1 failed; R5/R6 will be inconclusive"
  fi
  say "Setup is finished. Next: $STATE_NOTE A"
  pause
}

stage_rulesets() {
  stage "Create both rulesets"
  say "Branches: bypass is you alone, mode pull_request. Tags: bypass is you alone, mode always."
  say "First try actor_type User (row B3); if GitHub refuses, the repository admin role."
  begin_run person.sh lock "$LOGIN"
  local atype=User aid="$USER_ID" res=pass
  req "$ADMIN" POST /rulesets "$(branches_ruleset "$(bypass_json User "$USER_ID" pull_request)")"
  if [[ "$STATUS" == 201 ]]; then
    record B3 "accepted or refused (decides person vs role)" "$(observed): actor_type User accepted" info
  else
    record B3 "accepted or refused (decides person vs role)" "$(observed): actor_type User refused, using the admin role" info
    atype=RepositoryRole; aid=5
    req "$ADMIN" POST /rulesets "$(branches_ruleset "$(bypass_json RepositoryRole 5 pull_request)")"
  fi
  [[ "$STATUS" == 201 ]] || res=fail
  record RS1 "branches ruleset created (bypass $atype, mode pull_request)" "$(observed)" "$res"
  req "$ADMIN" POST /rulesets "$(tags_ruleset "$(bypass_json "$atype" "$aid" always)")"
  res=pass; [[ "$STATUS" == 201 ]] || res=fail
  record RS2 "tags ruleset created (bypass $atype, mode always)" "$(observed)" "$res"
  say "Ruleset ids: branches $(ruleset_id 'purlis: protected branches'), tags $(ruleset_id 'purlis: tags')"
  say "Next: $STATE_NOTE B   (then: person.sh $REPO press)"
  pause
}

stage_press() {
  stage "The person's rows"
  say "Your own acts under the lock, and the CI result of the chat's edited script."
  begin_run person.sh press "$LOGIN"
  local n sha res
  row_refused "$ADMIN" B2a "refused (your direct write to main, bypass mode pull_request)" PUT /contents/direct.txt \
    "{\"message\":\"direct\",\"content\":\"$(b64 direct)\",\"branch\":\"main\"}"
  n=$(pr_num "$ADMIN" vf-press)
  row_allowed "$ADMIN" B2b "allowed 200 (the person's press still merges)" "200" PUT "/pulls/$n/merge" '{"merge_method":"merge"}'
  req "$ADMIN" GET /git/ref/heads/main; sha=$(jqb T-admin1 -r .object.sha)
  row_allowed "$ADMIN" T-admin1 "allowed 201 (your tag, bypass always)" "201" POST /git/refs "{\"ref\":\"refs/tags/vadmin\",\"sha\":\"$sha\"}"
  row_allowed "$ADMIN" T-admin2 "allowed 204 (delete your tag)" "204" DELETE /git/refs/tags/vadmin
  req "$ADMIN" GET "/actions/runs?branch=vf-w1&per_page=1"
  res=info
  record W1c "run of the chat's edited script fails (its GITHUB_TOKEN could not write main); success is a CI-route gap" \
    "latest run: $(jqb W1c -r '[.workflow_runs[0].status, .workflow_runs[0].conclusion] | join(" / ")')" "$res"
  req "$ADMIN" GET "/contents/ci-wrote.txt?ref=main"
  record W1d "ci-wrote.txt absent from main" "$(observed)" "$([[ "$STATUS" == 404 ]] && echo pass || echo fail)"
  pause
}

stage_automerge() {
  stage "Auto-merge on, plus a required check"
  say "Turns on 'Allow auto-merge' as you, and requires the 'ci' check on main so a pull request is not already clean."
  confirm "Turn it on?" || die "stopped"
  req "$ADMIN" PATCH "" '{"allow_auto_merge":true}'; require_ok "allow_auto_merge"
  req "$ADMIN" POST /rulesets '{"name":"verify: require ci","target":"branch","enforcement":"active","conditions":{"ref_name":{"include":["~DEFAULT_BRANCH"],"exclude":[]}},"rules":[{"type":"required_status_checks","parameters":{"strict_required_status_checks_policy":false,"required_status_checks":[{"context":"ci"}]}}],"bypass_actors":[]}'
  require_ok "ci ruleset"
  say "Next: $STATE_NOTE C"
  pause
}

stage_bypass_app() { # on|off
  stage "The App as a bypass actor ($1)"
  ask APP_SLUG "The App's slug:"
  req_unscoped "$ADMIN" GET "/apps/$APP_SLUG"; local app_id; app_id=$(jqb "GET /apps/$APP_SLUG" -r .id)
  [[ "$app_id" =~ ^[0-9]+$ ]] || die "cannot read the App: $(observed)"
  local id; id=$(ruleset_id 'purlis: protected branches'); [[ -n "$id" ]] || die "branches ruleset not found"
  local actors
  if [[ "$1" == on ]]; then
    actors=$(jq -n --argjson a "$app_id" '[{actor_id:$a,actor_type:"Integration",bypass_mode:"always"}]')
  else
    actors='[]'
  fi
  req "$ADMIN" GET "/rulesets/$id"
  local cur new
  cur=$(jqb "BYP-$1" -c '.bypass_actors // []')
  new=$(jq -c --argjson add "$actors" --argjson app "$app_id" \
    '. as $c | ($c | map(select(.actor_type != "Integration" or .actor_id != $app))) + $add' <<<"$cur") || die "BYP-$1: jq failed building the bypass list"
  req "$ADMIN" PUT "/rulesets/$id" "$(jq -n --argjson b "$new" '{bypass_actors:$b}')"
  begin_run person.sh "bypass-app-$1" "$LOGIN"
  record "BYP-$1" "ruleset bypass list updated" "$(observed)" "$([[ "$STATUS" == 200 ]] && echo pass || echo fail)"
  [[ "$1" == on ]] && say "Next: NARROW_TOKEN=<contents:write-only token> chat.sh $REPO D (skipped without it), then person.sh $REPO bypass-app-off"
  pause
}

stage_delete() {
  stage "Delete the throwaway repo"
  req "$ADMIN" GET ""
  jq -e --arg m "$MARKER" '.description == $m and .private == false' <<<"$BODY" >/dev/null \
    || die "$REPO does not carry the throwaway marker; refusing to delete"
  warn "This permanently deletes $REPO. Commit the results file first."
  confirm "Delete $REPO?" || die "stopped"
  req "$ADMIN" DELETE ""
  if [[ "$STATUS" == 204 ]]; then say "Deleted."; else
    warn "refused: $(observed)"; say "Grant the scope and rerun: gh auth refresh -h github.com -s delete_repo"
  fi
  pause
}

run_wizard() {
case "$PHASE" in
  setup)  TOTAL_STAGES=3; banner "Forge lock verify: set up the throwaway repo"
          stage_create_repo; stage_install_app; stage_immutable ;;
  fixup)  TOTAL_STAGES=1; banner "Forge lock verify: fix up the repo"; stage_fixup ;;
  lock)   TOTAL_STAGES=1; banner "Forge lock verify: apply the lock"; stage_rulesets ;;
  press)  TOTAL_STAGES=1; banner "Forge lock verify: your own rows"; stage_press ;;
  automerge) TOTAL_STAGES=1; banner "Forge lock verify: auto-merge"; stage_automerge ;;
  bypass-app-on)  TOTAL_STAGES=1; banner "Forge lock verify: App bypass on"; stage_bypass_app on ;;
  bypass-app-off) TOTAL_STAGES=1; banner "Forge lock verify: App bypass off"; stage_bypass_app off ;;
  cleanup) TOTAL_STAGES=1; banner "Forge lock verify: delete the repo"; stage_delete ;;
  *) die "$USAGE" ;;
esac
finish
}

run_wizard "$@"; exit
